{
  "appearance_facts": [
    {
      "location": "Top-left title",
      "fact": "Title text reads 'Incidence of Condition A in US States'."
    },
    {
      "location": "Right-side legend",
      "fact": "Vertical color bar labeled 'High' at the top and 'Low' at the bottom, with tick values 0, 20, 40, 60, 80, 100. The scale runs from dark red (low) through orange to pale yellow (high)."
    },
    {
      "location": "Texas (TX)",
      "fact": "Large state polygon in the south-central region, labeled 'TX', filled with pale yellow color."
    },
    {
      "location": "Washington (WA)",
      "fact": "State polygon in the northwestern corner, labeled 'WA', filled with dark red color."
    },
    {
      "location": "Colorado (CO)",
      "fact": "State polygon in the western region, located east of Utah and west of Kansas, filled with light gray color."
    },
    {
      "location": "Other dark red states",
      "fact": "Minnesota (MN), Nebraska (NE), Oklahoma (OK), Georgia (GA), Florida (FL), and New York (NY) are also filled with dark red color."
    },
    {
      "location": "Other pale yellow states",
      "fact": "Montana (MT), North Dakota (ND), South Dakota (SD), Wyoming (WY), Utah (UT), Illinois (IL), West Virginia (WV), Virginia (VA), South Carolina (SC), and Massachusetts (MA) are filled with pale yellow color."
    },
    {
      "location": "Gray states",
      "fact": "California, Arizona, New Mexico (partially), Arkansas, Alabama, and Rhode Island are filled with light gray, distinct from the color scale."
    }
  ],
  "printed_facts": [
    {
      "location": "Legend axis",
      "fact": "Y-axis ticks: 0 (bottom, 'Low'), 20, 40, 60, 80, 100 (top, 'High'). Color gradient: Dark Red -> Orange -> Pale Yellow."
    },
    {
      "location": "State labels",
      "fact": "TX is labeled in the large southern state. WA is labeled in the northwest state. CO is the unlabeled gray state in the western interior (between UT and KS)."
    },
    {
      "location": "Color mapping",
      "fact": "Pale yellow corresponds to the top of the scale (approx 80-100). Dark red corresponds to the bottom of the scale (approx 0-20). Light gray is outside the scale range."
    }
  ],
  "public_definitions": [
    "Highest-incidence jurisdiction route",
    "Open Texas (TX) incidence profile for follow-up routing",
    "Open Washington (WA) incidence profile for follow-up routing",
    "Open Colorado (CO) incidence profile for follow-up routing"
  ],
  "uncertain": [
    "The specific numerical incidence value for Texas is not printed on the map, only its color (pale yellow) is visible.",
    "The specific numerical incidence value for Washington is not printed on the map, only its color (dark red) is visible.",
    "The specific numerical incidence value for Colorado is not printed on the map, and its color (gray) does not appear on the legend scale."
  ]
}
